function feedback(str,x,y)global scr visualbounds = Screen(scr.myimg,'TextBounds',str);pt = 0.012*length(str); % presentation timex  = x-bounds(3)/2;     % x positiony  = y-bounds(4)/2;     % y positionc  = visual.fgColor(1); % colorWaitSecs(0.2);nBlank = round(0.20*1/(scr.fd*scr.rate)); % fade out takes 0.2 secsfor f = 1:scr.rate    % Screen('BlendFunction', scr.myimg, GL_ONE, GL_ZERO);    Screen('FillRect', scr.myimg, visual.bgColor);    Screen('Drawtext', scr.myimg, str,x,y,c);    PsychProPixx('QueueImage', scr.myimg);endWaitSecs(round(0.2/(scr.fd*scr.rate))*scr.fd*scr.rate - scr.fd*scr.rate);% for i = 1:nBlank% 	c = round(visual.fgColor(1)+(visual.bgColor(1)-visual.fgColor(1))*i/nBlank);% 	 % rubber([x y x+width y+const.FONT_SIZE]);% 	Screen(scr.main,'Drawtext',str,x,y,c);	%     for f = 1:scr.rate%         PsychProPixx('QueueImage', scr.myimg);%     end% endfor f = 1:scr.rate    Screen('FillRect', scr.myimg, visual.bgColor);    PsychProPixx('QueueImage', scr.myimg);end